begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
set local role rafik_user;
select set_config('rafik.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"rafik_user"}',true);
do $$ declare draft jsonb; p public.plans; v public.plan_versions; a public.assignments; s jsonb; entries jsonb; result jsonb; op uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); before jsonb; completed text; progress jsonb; begin
 draft:='{"schema":1,"days":[{"id":"r5-choice","name":"Choice session","exercises":[{"key":"squat","exerciseId":"goblet-squat","kind":"strength","sets":2,"reps":8,"load":8,"unit":"kg","rest":60,"note":"","alternatives":[{"exerciseId":"split-squat","info":{"name":"Forged"}}]}]}]}';
 perform public.save_plan(gen_random_uuid(),'Alternative validation',draft,null);
 perform pg_temp.assert(true,'valid bounded same-kind alternative accepted');
 begin perform public.save_plan(gen_random_uuid(),'Validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"forearm-plank"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternative' then raise;end if;end;
 perform pg_temp.assert(true,'cross-kind alternatives cannot reuse incompatible targets');
 begin perform public.save_plan(gen_random_uuid(),'Validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"split-squat"},{"exerciseId":"floor-press"},{"exerciseId":"glute-bridge"},{"exerciseId":"band-row"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternatives' then raise;end if;end;
 perform pg_temp.assert(true,'more than three alternatives rejected');
 perform public.save_exercise('r5-private-alternative','{"name":"Private squat","name_ar":"قرفصاء خاصة","equipment":"","equipment_ar":"","instructions":"Steady","instructions_ar":"بهدوء","movement":"squat","kind":"strength","media_url":""}',0);
 perform public.save_exercise('r14-media-choice','{"name":"Squat illustration","instructions":"Controlled movement","kind":"strength","media_ref":"wg-aac5992-goblet-squat"}',0);
 perform pg_temp.assert((select media_ref='wg-aac5992-goblet-squat' from exercises where id='r14-media-choice'),'coach can select an approved illustration');
 p:=public.save_plan(gen_random_uuid(),'Media snapshot',draft,null);v:=public.publish_plan(p.id,p.draft_version);
 perform pg_temp.assert(v.prescription#>>'{days,0,exercises,0,info,media_ref}'='wg-aac5992-goblet-squat','published prescription captures immutable media reference');
 begin perform public.save_exercise('r14-invalid-media','{"name":"Invalid","instructions":"Invalid","kind":"strength","media_ref":"arbitrary-external-asset"}',0);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_exercise' then raise;end if;end;
 perform pg_temp.assert(true,'unknown managed media rejected');
 perform public.set_exercise_active('r5-private-alternative',false);
 begin perform public.save_plan(gen_random_uuid(),'Validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"r5-private-alternative"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternative' then raise;end if;end;
 perform pg_temp.assert(true,'retired draft alternative rejected');
 perform public.set_exercise_active('r5-private-alternative',true);
 perform set_config('rafik.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"rafik_user"}',true);
 begin perform public.save_plan(gen_random_uuid(),'Validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"r5-private-alternative"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternative' then raise;end if;end;
 perform pg_temp.assert(true,'another coach cannot publish private alternatives');
 perform set_config('rafik.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"rafik_user"}',true);

 begin perform public.save_plan(gen_random_uuid(),'Alternative validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"goblet-squat"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternative' then raise;end if;end;
 perform pg_temp.assert(true,'original cannot be its own alternative');
 begin perform public.save_plan(gen_random_uuid(),'Alternative validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"split-squat"},{"exerciseId":"split-squat"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternative' then raise;end if;end;
 perform pg_temp.assert(true,'duplicate alternatives rejected');
 begin perform public.save_plan(gen_random_uuid(),'Alternative validation',jsonb_set(draft,'{days,0,exercises,0,alternatives}','[{"exerciseId":"not-owned"}]'),null);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_alternative' then raise;end if;end;
 perform pg_temp.assert(true,'unknown or inaccessible alternative rejected');
 p:=public.save_plan('29000000-0000-4000-8000-000000000001','R5 choice',draft,null);
 v:=public.publish_plan(p.id,p.draft_version);
 perform pg_temp.assert(v.prescription#>>'{days,0,exercises,0,alternatives,0,info,name}'=(select name from public.exercises where id='split-squat'),'publication replaces untrusted alternative info with catalog snapshot');
 a:=public.assign_plan('40000000-0000-4000-8000-000000000001',v.id);
 perform set_config('rafik.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"rafik_user"}',true);
 s:=public.start_session(sid,v.id,'r5-choice',a.id);before:=s->'prescription';
 select jsonb_agg(x||'{"exercise_id":"split-squat","completed":true}'::jsonb) into entries from jsonb_array_elements(s->'entries') x;
 result:=public.save_session(sid,1,op,entries,'Used approved alternative',true);
 completed:=result->>'completed_at';
 perform pg_temp.assert(result#>>'{entries,0,exercise_id}'='split-squat' and result->'prescription'=before,'actual choice saved while prescribed snapshot stays immutable');
 perform pg_temp.assert(public.save_session(sid,1,op,entries,'Used approved alternative',true)=result,'exact substitution/completion retry replays receipt');
 begin perform public.save_session(sid,1,op,jsonb_set(entries,'{0,exercise_id}','"goblet-squat"'),'Used approved alternative',true);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'operation_reused' then raise;end if;end;
 perform pg_temp.assert(true,'operation ID cannot be reused for changed choice');
 begin perform public.save_session(sid,2,gen_random_uuid(),jsonb_set(entries,'{0,exercise_id}','"goblet-squat"'),'',false);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'inconsistent_exercise_choice' then raise;end if;end;
 perform pg_temp.assert(true,'different choices across sets rejected atomically');
 begin perform public.save_session(sid,2,gen_random_uuid(),(select jsonb_agg(x||'{"exercise_id":"unapproved"}'::jsonb) from jsonb_array_elements(entries) x),'',false);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'invalid_exercise_choice' then raise;end if;end;
 perform pg_temp.assert((public.session_document(sid)->>'version')::int=2,'unapproved exercise rejected without version or entry changes');
 progress:=public.training_progress(null,current_date-1,current_date+1);
 perform pg_temp.assert(exists(select 1 from jsonb_array_elements(progress) x where x->>'id'=sid::text and x#>>'{exercises,0,id}'='split-squat'),'progress identifies actual exercise');
 perform pg_temp.assert(exists(select 1 from jsonb_array_elements(public.previous_performance(array['split-squat'],now()+interval '1 minute')) x where x->>'exercise_id'='split-squat' and x#>>'{prescription,info,name}'=(select name from public.exercises where id='split-squat')),'previous performance uses actual identity and frozen instructions');
 select jsonb_agg(x||'{"exercise_id":"goblet-squat"}'::jsonb) into entries from jsonb_array_elements(entries) x;
 result:=public.save_session(sid,2,gen_random_uuid(),entries,'Corrected identity',true);
 perform pg_temp.assert(result->>'completed_at'=completed and result->'prescription'=before,'returning to original keeps completion date and prescription');
 perform set_config('rafik.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"rafik_user"}',true);
 begin perform public.save_session(sid,3,gen_random_uuid(),entries,'',false);raise exception 'accepted';exception when raise_exception then if sqlerrm<>'forbidden' then raise;end if;end;
 perform pg_temp.assert(true,'unrelated account cannot change actual choice');
end $$;
reset role;
do $$ declare p public.plans; snapshot jsonb; copied text; begin
 select prescription into snapshot from public.plan_versions where plan_id='29000000-0000-4000-8000-000000000001';
 p:=public.copy_snapshot_plan(gen_random_uuid(),'10000000-0000-4000-8000-000000000004','Independent choice',snapshot);
 copied:=p.draft#>>'{days,0,exercises,0,alternatives,0,exerciseId}';
 perform pg_temp.assert(copied<>'split-squat' and exists(select 1 from public.exercises where id=copied and owner_id='10000000-0000-4000-8000-000000000004'),'shared/handoff snapshot copy independently owns alternatives');
 perform set_config('rafik.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"rafik_user"}',true);
 perform public.validate_prescription(p.draft);
 perform pg_temp.assert(true,'imported alternative can be edited and republished by receiving coach');
end $$;
rollback;
